#!/bin/bash
# Task 088 -- meshsim v1.2.1 verification (WORKER15): branch v1.2.1 (090fc40), the v1.2 spec, simulator and software
# brought in line (errata E1-E9, cleanups CL1-CL5; CL1 moves the replayer's queue ports: write log 0x300000, expansion
# 0x400000).
#  1. run_tests.sh's quick suite (every "$J" step outside full mode), 8 at a time (tools/run_quick.sh);
#  2. its full-mode extras (CtrlTest/AccountingTest/ReadPortGatherTest/EngineTest full, the sweep, AgBench, the skew
#     table, S1Bench, the sort's two BT runs at 64 x 16,384), 4 at a time (tools/run_full.sh);
#  3. the full-size sort: p4/uniform-k128 at 64 x 65,536 (task 086's sortrunner; jar rebuilt from v1.2.1 at
#     --release 17; the sort image, boot ROM and hops.txt byte-identical to 077/086's; HASHES updated for the jar).
# The kit (v1.2.1/meshsim built at Java 17 with every image prebuilt, v1.2.1/sw, the opcode vectors; sortrunner/) is
# embedded below, SHA-256 checked; smoke-tested locally (run_quick on bus/regdoc/replayer/reqbus/riscv/stageb, run_p4
# at n = 2,000). Expected ~15 min (086 took 14).
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/088-w15-v121-verify; mkdir -p "$RES"
WANT=5758d7d34d5869aa49210a259d024c3bd7426c0fa20ffb637a982af7ee2c126c
W=/tmp/w15-088; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
cd "$W/v1.2.1/meshsim" || exit 2
P=8 bash tools/run_quick.sh "$W/out"; RQ=$?
P=4 bash tools/run_full.sh "$W/out"; RF=$?
cd "$W/sortrunner" || exit 2
printf 'p4/uniform-k128\n' > "$W/p4list"
bash ./run_p4.sh -j 1 -m 6g -l "$W/p4list" "$W/p4"; RS=$?
echo "run_quick.sh exit $RQ, run_full.sh exit $RF, run_p4.sh exit $RS at $(date -u)"
mkdir -p "$RES/p4"; cp "$W"/out/* "$RES/" 2>/dev/null; cp "$W"/p4/* "$RES/p4/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/out/FULL-VERDICT.txt" "$W/p4/VERDICT.txt" 2>/dev/null
rm -rf "$W"
[ $RQ = 0 ] && [ $RF = 0 ] && [ $RS = 0 ]; exit $?
